local KilnFurnitureMaker = {}
local PRODUCTS = {
    iron_kiln_furniture = { name = "Železne pešice za peči", ironCost = 4, woodCost = 1, leatherCost = 1, time = 5, cost = 180, prestige = 4, happiness = 2, description = "Železne pešice za podporo keramike v peči." },
    bronze_kiln_furniture = { name = "Bronaste pešice za peči", bronzeCost = 4, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 435, prestige = 6, happiness = 3, description = "Bronaste pešice za stabilno žganje." },
    silver_kiln_furniture = { name = "Srebrne pešice za peči", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 1050, prestige = 11, happiness = 4, description = "Srebrne pešice za plemiške peči." },
    gilded_kiln_furniture = { name = "Pozlačene pešice za peči", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 2250, prestige = 20, happiness = 5, description = "Pozlačene pešice za dvorne peči." },
    jewel_set_kiln_furniture = { name = "Draguljaste pešice za peči", goldCost = 2, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 4850, prestige = 36, happiness = 7, description = "Draguljaste pešice za kraljevske peči." },
    royal_sovereign_kiln_furniture = { name = "Kraljevski suverene pešice za peči", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 10400, prestige = 68, happiness = 13, description = "Suverene pešice z biseri za krono." },
}
local BUILDINGS = {
    kilnfurniture_workshop = { name = "Pešična delavnica", cost = { gold = 365, wood = 175, stone = 145, iron = 9 }, upkeep = 7, qualityBonus = 5 },
    kilnfurniture_house = { name = "Pešična hiša", cost = { gold = 1285, wood = 360, stone = 290, silver = 8, iron = 8 }, upkeep = 27, qualityBonus = 18 },
    master_kilnfurniture_atelier = { name = "Mojstrski pešični atelje", cost = { gold = 3200, wood = 420, stone = 545, silver = 39, gold = 8 }, upkeep = 75, qualityBonus = 30 },
    sovereign_kilnfurniture_palace = { name = "Suverena pešična palača", cost = { gold = 13600, wood = 650, stone = 860, gold = 88, jewel = 20 }, upkeep = 263, qualityBonus = 55, prestigeBonus = 50 },
}
KilnFurnitureMaker.ironStock = 16; KilnFurnitureMaker.bronzeStock = 14; KilnFurnitureMaker.woodStock = 10; KilnFurnitureMaker.leatherStock = 8; KilnFurnitureMaker.silverStock = 8; KilnFurnitureMaker.goldStock = 6; KilnFurnitureMaker.jewelStock = 4; KilnFurnitureMaker.pearlStock = 4
KilnFurnitureMaker.productStock = {}; KilnFurnitureMaker.buildings = {}; KilnFurnitureMaker.maker = nil; KilnFurnitureMaker.activeMaking = {}; KilnFurnitureMaker.totalProducts = 0; KilnFurnitureMaker.dayTimer = 0
function KilnFurnitureMaker.init() KilnFurnitureMaker.ironStock=16; KilnFurnitureMaker.bronzeStock=14; KilnFurnitureMaker.woodStock=10; KilnFurnitureMaker.leatherStock=8; KilnFurnitureMaker.silverStock=8; KilnFurnitureMaker.goldStock=6; KilnFurnitureMaker.jewelStock=4; KilnFurnitureMaker.pearlStock=4; KilnFurnitureMaker.productStock={}; KilnFurnitureMaker.buildings={}; KilnFurnitureMaker.maker=nil; KilnFurnitureMaker.activeMaking={}; KilnFurnitureMaker.totalProducts=0; KilnFurnitureMaker.dayTimer=0; print("[KilnFurnitureMaker] Royal Kiln Furniture Maker System initialized (6 products, 4 buildings)") end
function KilnFurnitureMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; KilnFurnitureMaker.maker={name=n or ("Pešičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pešičar najet: %s (spretnost: %d)",KilnFurnitureMaker.maker.name,s),"success") end; return true end
function KilnFurnitureMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function KilnFurnitureMaker.build(id) local ok,e=KilnFurnitureMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(KilnFurnitureMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function KilnFurnitureMaker.getQualityBonus() local b=0; for _,bd in ipairs(KilnFurnitureMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function KilnFurnitureMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and KilnFurnitureMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and KilnFurnitureMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and KilnFurnitureMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and KilnFurnitureMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and KilnFurnitureMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and KilnFurnitureMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and KilnFurnitureMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and KilnFurnitureMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #KilnFurnitureMaker.buildings==0 then return false,"Potrebna pešična delavnica" end; if not KilnFurnitureMaker.maker then return false,"Potreben pešičar" end; return true end
function KilnFurnitureMaker.make(pt,qty) qty=qty or 1; local ok,e=KilnFurnitureMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then KilnFurnitureMaker.ironStock=KilnFurnitureMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then KilnFurnitureMaker.bronzeStock=KilnFurnitureMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then KilnFurnitureMaker.woodStock=KilnFurnitureMaker.woodStock-d.woodCost*qty end; if d.leatherCost then KilnFurnitureMaker.leatherStock=KilnFurnitureMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then KilnFurnitureMaker.silverStock=KilnFurnitureMaker.silverStock-d.silverCost*qty end; if d.goldCost then KilnFurnitureMaker.goldStock=KilnFurnitureMaker.goldStock-d.goldCost*qty end; if d.jewelCost then KilnFurnitureMaker.jewelStock=KilnFurnitureMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then KilnFurnitureMaker.pearlStock=KilnFurnitureMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if KilnFurnitureMaker.maker then t=math.max(1,t-math.floor(KilnFurnitureMaker.maker.skill/13)) end; table.insert(KilnFurnitureMaker.activeMaking,{id="kilnfurniture_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function KilnFurnitureMaker.completeMaking(m) local q=1.0+(KilnFurnitureMaker.getQualityBonus()/100); if KilnFurnitureMaker.maker then q=q+(KilnFurnitureMaker.maker.skill/140) end; q=math.min(2.5,q); KilnFurnitureMaker.productStock[m.productType]=(KilnFurnitureMaker.productStock[m.productType] or 0)+m.quantity; KilnFurnitureMaker.totalProducts=KilnFurnitureMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if KilnFurnitureMaker.maker then KilnFurnitureMaker.maker.itemsMade=KilnFurnitureMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then KilnFurnitureMaker.maker.skill=math.min(100,KilnFurnitureMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pešica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"kilnfurniture.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function KilnFurnitureMaker.update(dt) if not _G.state then return end; KilnFurnitureMaker.dayTimer=KilnFurnitureMaker.dayTimer+dt; if KilnFurnitureMaker.dayTimer>=30 then KilnFurnitureMaker.dayTimer=0; for i=#KilnFurnitureMaker.activeMaking,1,-1 do local m=KilnFurnitureMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then KilnFurnitureMaker.completeMaking(m); table.remove(KilnFurnitureMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(KilnFurnitureMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if KilnFurnitureMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function KilnFurnitureMaker.getStats() return {ironStock=KilnFurnitureMaker.ironStock,bronzeStock=KilnFurnitureMaker.bronzeStock,woodStock=KilnFurnitureMaker.woodStock,leatherStock=KilnFurnitureMaker.leatherStock,silverStock=KilnFurnitureMaker.silverStock,goldStock=KilnFurnitureMaker.goldStock,jewelStock=KilnFurnitureMaker.jewelStock,pearlStock=KilnFurnitureMaker.pearlStock,productStock=KilnFurnitureMaker.productStock,numBuildings=#KilnFurnitureMaker.buildings,hasMaker=KilnFurnitureMaker.maker~=nil,makerName=KilnFurnitureMaker.maker and KilnFurnitureMaker.maker.name or "—",makerSkill=KilnFurnitureMaker.maker and KilnFurnitureMaker.maker.skill or 0,activeMaking=#KilnFurnitureMaker.activeMaking,totalProducts=KilnFurnitureMaker.totalProducts} end
return KilnFurnitureMaker
